def create_producer_group(apps, schema_editor):
    Group = apps.get_model("auth", "Group")
    Permission = apps.get_model("auth", "Permission")
    ContentType = apps.get_model("contenttypes", "ContentType")

    # Crear el grupo si no existe
    group, created = Group.objects.get_or_create(name="Productor")

    # Apps a incluir
    apps_to_include = ["producer", "input", "operation", "sale"]

    # SI quiero que solo sea un modelo
    #staff_ct = ContentType.objects.get(app_label="producer", model="staff")
    
    
    # Buscar todos los contenttypes de esas apps
    cts = ContentType.objects.filter(app_label__in=apps_to_include)

    # Traer todos los permisos asociados a esos contenttypes
    permissions = Permission.objects.filter(content_type__in=cts)

    # Asignarlos al grupo
    group.permissions.add(*permissions)
    group.save()

